    private function guides(): array
    {
        $rows = [
            'giulia' => ['Джулия Маркетти', 'italy', 'Амальфи', 'Побережья, ремесло и итальянская кухня', 'Итальянский, русский, английский', 'Родилась в Амальфи, выросла между лимонными террасами и мастерской бумаги. Показывает побережье так, как его видят жители.', 'Моя бабушка делала бумагу по технологии XIII века, и я до сих пор слышу, как шуршат листы в её мастерской. Десять лет назад я вернулась в Амальфи из Милана — и поняла, что хочу показывать людям не открытку, а настоящий день на побережье: с булочной в семь утра, с рыбаками у причала и ужином, который не торопится.', 'Хороший день на побережье начинается с тишины.', 'giulia@viabella.test', 11, 'guides/giulia'],
            'elena' => ['Елена Риччи', 'italy', 'Флоренция', 'Вино, рынки и тосканская кухня', 'Итальянский, русский, английский', 'Сомелье и автор гастрономических маршрутов по Тоскане. Знает винодельни, куда не попасть без рекомендации.', 'Я выросла на семейной винодельне близ Монтепульчано. Потом были Флоренция, курсы сомелье и несколько лет в ресторанах. Сегодня я вожу гостей по погребам друзей и готовлю с ними пасту на кухнях, где нет ни одной вывески.', 'Хороший обед — это разговор, который не хочется заканчивать.', 'elena@viabella.test', 9, 'guides/elena'],
            'julien' => ['Жюльен Моро', 'france', 'Париж', 'Искусство, архитектура и тихий Париж', 'Французский, русский, английский', 'Историк искусства. Водит по Парижу и Ривьере так, как показывал бы родной город другу.', 'Я родился на Монмартре и до сих пор живу в двух кварталах от дома, где вырос. Много лет работал в музее, а потом понял, что лучшие лекции читаются на улице. Я знаю, где пахнет свежим багетом в шесть утра и с какой крыши виден весь город.', 'Париж открывается тем, кто умеет идти медленно.', 'julien@viabella.test', 14, 'guides/julien'],
            'nikos' => ['Никос Александру', 'greece', 'Ия', 'Острова, закаты и греческая кухня', 'Греческий, английский, русский', 'Капитан небольшой лодки и гид по Санторини. Знает бухты, до которых не добираются круизные лайнеры.', 'Мой отец ловил рыбу в кальдере, а я возил туда друзей на лодке — сначала просто так, потом стал делать это профессионально. Для меня остров — это не закат в Ие, а двадцать мест, о которых знают только местные.', 'Остров показывает себя тому, кто не спешит.', 'nikos@viabella.test', 12, 'guides/nikos'],
            'anna' => ['Анна Келлер', 'switzerland', 'Гриндельвальд', 'Горы, тропы и железные дороги', 'Немецкий, английский, русский', 'Горный гид и фотограф. Строит маршруты так, чтобы утро всегда начиналось со света на вершинах.', 'Я выросла в Бернском Оберланде и в десять лет впервые прошла к ледяному озеру. Сегодня я составляю маршруты, в которых нет ни одного лишнего перехода: только тишина, водопады и поезда, идущие по самым красивым линиям Швейцарии.', 'Горы учат нас идти в своём темпе.', 'anna@viabella.test', 10, 'guides/anna'],
            'franz' => ['Франц Грубер', 'austria', 'Вена', 'История, музыка и кофейная культура', 'Немецкий, английский, русский', 'Историк и музыкант. Рассказывает о Вене и Зальцкаммергуте через композиторов, кофейни и людей.', 'Тридцать лет я играл на виолончели в оркестре и теперь с тем же вниманием слушаю города. В Вене я показываю гостям кофейни, где писал Малер, а в Гальштате — тихое озеро на рассвете, которого не знают туристы.', 'Лучшие города звучат тихо.', 'franz@viabella.test', 22, 'guides/franz'],
        ];
        $out = [];
        foreach ($rows as $k => $r) {
            $out[$k] = Guide::create([
                'name' => $r[0], 'slug' => $k, 'country' => $r[1], 'city' => $r[2], 'specialization' => $r[3], 'languages' => $r[4],
                'description' => $r[5], 'story' => $r[6], 'quote' => $r[7], 'contact_information' => $r[8], 'experience_years' => $r[9],
                'photo' => 'img/' . $r[10] . '.jpg',
            ]);
        }

        return $out;
    }

