                'program' => array_map(fn ($p, $i) => ['day' => $kind === 'excursion' ? '' : 'День ' . ($i + 1), 'title' => $p[0], 'text' => $p[1]], $prog, array_keys($prog)),
                'included' => $kind === 'tour'
                    ? ['Проживание в бутик-отелях', 'Завтраки и часть ужинов', 'Авторские экскурсии с гидом', 'Трансферы по маршруту']
                    : ['Сопровождение гида', 'Дегустации и входные билеты', 'Небольшая группа до 8 человек'],
                'lat' => $lat, 'lng' => $lng, 'accent' => $accent,
            ]);
        }

        return $tours;
    }

    private function authors(): array
    {
        $rows = [
            ['Мария Соколова', 'maria@viabella.test', 'Москва', 'avatars/maria'],
            ['Ольга Лебедева', 'olga@viabella.test', 'Санкт-Петербург', 'avatars/olga'],
            ['Дмитрий Орлов', 'dmitry@viabella.test', 'Казань', 'avatars/dmitry'],
            ['Софья Белова', 'sofia@viabella.test', 'Москва', 'avatars/sofia'],
            ['Артём Крылов', 'artem@viabella.test', 'Екатеринбург', 'avatars/artem'],
        ];
        $out = [];
        foreach ($rows as $r) {
            $out[] = User::create(['name' => $r[0], 'email' => $r[1], 'password' => 'Travel12345', 'city' => $r[2], 'avatar' => 'img/' . $r[3] . '.jpg', 'role' => 'user']);
        }

        return $out;
    }

    private function scheduleAndReviews(array $tours, array $authors, User $demo): void
    {
        $texts = [
            ['Утро, которое я не забуду', 'Мы ожидали красивые виды, но получили нечто большее — ощущение, что нас пустили в чужой дом. Гид знал каждого булочника по имени, а ужин на террасе растянулся на три часа. Вернулись с чувством, что отдохнули по-настоящему.'],
            ['Спокойно и очень красиво', 'Маленькая группа — это огромная разница. Никакой спешки, ни одного лишнего перехода. Особенно запомнился обед у местной семьи: простая еда, но такая, которую хочется вспоминать.'],
            ['Лучшая поездка за последние годы', 'Я не любитель организованных туров, но здесь всё иначе: программа продумана, а гид умеет оставить время для собственных открытий. Фотографий привезла столько, что хватит на альбом.'],
            ['Живые истории вместо экскурсии по списку', 'Нам рассказывали не даты, а людей и места. Узкие улочки, виды, вино — всё сложилось в одну историю. Поеду ещё раз, уже с родителями.'],
            ['Отличная организация', 'Трансферы без опозданий, отели — как на картинках, гид всегда на связи. Единственный минус: хотелось ещё пару дней.'],
        ];

        $i = 0;
        foreach ($tours as $tour) {
            $days = $tour->kind === 'excursion' ? [12, 26, 41, 63, 88] : [24, 49, 78, 112, 150];
            foreach ($days as $n => $d) {
                $cap = $tour->kind === 'excursion' ? 8 : 10;
                Schedule::create([
                    'tour_id' => $tour->id, 'starts_at' => now()->addDays($d)->setTime($tour->kind === 'excursion' ? 7 : 9, 0),
                    'ends_at' => now()->addDays($d + $tour->duration - 1)->setTime(18, 0), 'capacity' => $cap, 'status' => 'open',
                ]);
            }
            // Состоявшийся сеанс в прошлом — для настоящих отзывов
            $past = Schedule::create([
                'tour_id' => $tour->id, 'starts_at' => now()->subDays(40 + $i)->setTime(9, 0),
                'ends_at' => now()->subDays(40 + $i - $tour->duration + 1)->setTime(18, 0), 'capacity' => 10, 'status' => 'open',
            ]);
            foreach (array_slice($authors, 0, 3 + ($i % 2)) as $k => $author) {
                $t = $texts[($i + $k) % count($texts)];
                $b = Booking::create([
                    'reference' => 'VB-' . strtoupper(substr(md5("$i-$k"), 0, 6)), 'user_id' => $author->id, 'schedule_id' => $past->id,
                    'participants_count' => 1 + $k % 2, 'status' => 'confirmed', 'unit_price' => $tour->price, 'total_price' => $tour->price * (1 + $k % 2),
                    'contact_name' => $author->name, 'contact_email' => $author->email, 'contact_phone' => '+7 900 111-22-3' . $k,
                ]);
                Review::create([
                    'user_id' => $author->id, 'tour_id' => $tour->id, 'booking_id' => $b->id, 'rating' => ($i + $k) % 5 === 4 ? 4 : 5,
                    'title' => $t[0], 'text' => $t[1], 'photo' => ($tour->gallery[$k % count($tour->gallery)] ?? $tour->cover), 'created_at' => now()->subDays(30 + $i + $k),
                ]);
            }
            $i++;
        }

        // Демо-аккаунт: одна прошедшая поездка без отзыва (можно оставить отзыв) и одна будущая заявка
        $amalfi = $tours['amalfi-golden-hour'];
        $past = Schedule::create(['tour_id' => $amalfi->id, 'starts_at' => now()->subDays(20)->setTime(9, 0), 'ends_at' => now()->subDays(15)->setTime(18, 0), 'capacity' => 10, 'status' => 'open']);
        Booking::create(['reference' => 'VB-DEMO01', 'user_id' => $demo->id, 'schedule_id' => $past->id, 'participants_count' => 2, 'status' => 'confirmed', 'unit_price' => $amalfi->price, 'total_price' => $amalfi->price * 2, 'contact_name' => $demo->name, 'contact_email' => $demo->email, 'contact_phone' => '+7 900 000-00-00']);
    }
}
